const courseName=id=>allCourses().find(c=>c.id===id)?.name||'Personal course';
const courseLessons=id=>LESSONS.filter(l=>l.courseId===id);
const dateLabel=(s,short=false)=>s?.length===7?new Intl.DateTimeFormat('en',{month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(s+'-01T12:00:00Z')):new Intl.DateTimeFormat('en',{month:'short',day:'numeric',...(short?{}:{year:'numeric'}),timeZone:'Asia/Bangkok'}).format(new Date(s));
const toggle=(arr,id)=>arr.includes(id)?arr.filter(x=>x!==id):[...arr,id];
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function persist(){try{if(storageError)throw Error('Existing browser data could not be loaded. Export it in Settings before recovery.');saveState(state);contentDirty=true;return true;}catch(err){toast(err.message||'Could not save. Export a backup before closing this tab.');return false;}}
const sectionNames={home:'The Daily',library:'My Bookshelf',study:'Study Room',news:'Market Pulse',saved:'Saved Stories',settings:'Settings'};
const detailParents={course:'library',reader:'library',lesson:'study',practice:'study'};
const detailViews={course:null,reader:null,lesson:null,practice:null};
let scrollFrame=0,contentDirty=false;
function go(path){
 if(location.hash!=='#'+path)history.pushState(null,'','#'+path);
 navigateToHash();
}
function setActiveSection(key){
 const parent=detailParents[key]||key;
 document.querySelectorAll('.nav-item').forEach(link=>{
  const active=link.hash==='#'+parent;
  link.classList.toggle('active',active);
  if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');
 });
 const crumb=$('.crumb strong');if(crumb)crumb.textContent=sectionNames[parent]||sectionNames.home;
}
function scrollToSection(key,smooth=true){
 const section=document.getElementById(key);if(!section)return;
 section.focus({preventScroll:true});
 section.scrollIntoView({block:'start',behavior:smooth&&!matchMedia('(prefers-reduced-motion: reduce)').matches?'smooth':'instant'});
 setActiveSection(key);
}
function navigateToHash(smooth=true){
 if(!reference)return;
 [route='home',param='']=location.hash.slice(1).split('/');if(!route)route='home';
 if(route==='goals'){history.replaceState(null,'','#home');route='home';param='';}
 if(route==='main'){document.getElementById('main')?.focus();return;}
 if(modal.open)closeModal();
 let needsRender=contentDirty;
 if(Object.hasOwn(detailViews,route)){
  const path=route+(param?'/'+param:'');
  if(detailViews[route]!==path||!document.getElementById(route)){detailViews[route]=path;needsRender=true;}
 }
 if(needsRender)render();
 if(!document.getElementById(route)){toast('This section could not be found. Your progress is safe.');route='home';}
 $('.sidebar')?.classList.remove('open');$('.mobile-menu')?.setAttribute('aria-expanded','false');
 scrollToSection(route,smooth);
}
function nav(path,label,name,count){const accessible=count===undefined?label:label+' ('+count+')';return `<a href="#${path}" aria-label="${e(accessible)}" title="${e(accessible)}" class="nav-item ${route===path||(path==='library'&&['course','reader'].includes(route))||(path==='study'&&['lesson','practice'].includes(route))?'active':''}" ${route===path?'aria-current="page"':''}>${icon(name)}<span>${label}</span>${count!==undefined?`<span class="nav-count">${count}</span>`:''}</a>`;}
function shell(content){
 const dark=document.documentElement.dataset.theme==='dark';
 app.innerHTML=`<aside class="sidebar" aria-label="Main navigation"><a href="#home" class="brand" aria-label="Zin's studio · The Daily" title="The Daily"><span class="brand-mark">z.</span><span><span class="brand-name">zin's studio</span><span class="brand-sub">a curious little mind</span></span></a><div class="nav-label">YOUR SPACE</div><nav>${nav('home','The Daily','home')}${nav('library','My Bookshelf','book')}${nav('study','Study Room','study')}<div class="nav-section"><div class="nav-label">COLLECT & CONNECT</div>${nav('news','Market Pulse','globe')}${nav('saved','Saved Stories','bookmark',state.saved.length)}</div></nav><div class="sidebar-bottom"><div class="cat-note"><img src="assets/avatar.webp" alt="A little black cat reading in the snow"><p>Big ideas.<br>Little steps. You’ve got this.</p><small>Your next chapter is waiting.</small></div>${nav('settings','Studio Settings','settings')}<div class="profile"><img class="avatar" src="assets/avatar.webp" alt=""><div><strong>Zin</strong><span>Marketing student · VNUIS</span></div>${icon('spark',15)}</div></div></aside><div class="shell"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Toggle navigation" aria-expanded="false">${icon('menu')}</button><span class="crumb">My workspace <span style="padding:0 8px">/</span><strong>${({home:'The Daily',library:'My Bookshelf',study:'Study Room',news:'Market Pulse',saved:'Saved Stories',settings:'Settings',course:'My Bookshelf',reader:'Reading Room',lesson:'Study Room',practice:'Recall Session'})[route]||'The Daily'}</strong></span><form class="search" id="global-search" role="search">${icon('search',16)}<input name="query" aria-label="Search courses and books" placeholder="Find a course or a book…" autocomplete="off"><span class="key">/</span></form><button class="icon-btn" data-action="theme" aria-label="Switch to ${dark?'light':'dark'} mode" title="Switch to ${dark?'light':'dark'} mode">${icon(dark?'sun':'moon')}</button><span class="topbar-divider"></span><img src="assets/avatar.webp" class="avatar" alt="Zin's cat avatar"></header><main id="main" class="content" tabindex="-1">${storageError?`<div class="error">Saved data needs attention. ${e(storageError)} <a href="#settings">Open Settings</a></div>`:''}${content}<footer class="footer"><span>Made for your curious mind, Zin. ${icon('heart',10)}</span><span>Private studio · Progress saved on this browser <button class="text-btn" data-action="backup">Back up ${icon('download',12)}</button></span></footer></main></div>`;
}
function weeklyChart(){
 const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Bangkok'});
 const anchor=new Date(today+'T12:00:00+07:00');
 const days=Array.from({length:7},(_,i)=>{const d=new Date(anchor.getTime()-(6-i)*DAY);const date=d.toLocaleDateString('en-CA',{timeZone:'Asia/Bangkok'});return {label:d.toLocaleDateString('en',{weekday:'narrow',timeZone:'Asia/Bangkok'}),count:state.attempts.filter(a=>new Date(a.at).toLocaleDateString('en-CA',{timeZone:'Asia/Bangkok'})===date).length,date};});
 const max=Math.max(1,...days.map(d=>d.count));
 return `<div class="week-chart" role="img" aria-label="Review attempts over the last seven days: ${days.map(d=>`${d.date}: ${d.count}`).join('; ')}">${days.map(d=>`<div class="week-day" title="${d.date}: ${d.count} attempts"><span class="week-bar ${d.count?'':'empty'}" style="height:${d.count?Math.max(8,d.count/max*60):4}px"></span><span>${d.label}</span></div>`).join('')}</div>`;
}
function allNews(){return [...new Map([...ARCHIVED_NEWS,...archivedStories(),...reading.items].map(n=>[n.id,n])).values()];}
function newsItems(){const items=reading.items.filter(n=>!state.hidden.includes(n.id));const sorted=[...items].sort((a,b)=>b.date.localeCompare(a.date));const lead=[];for(const key of ['vne-business','google-ads','vne-world']){const n=sorted.find(n=>n.sourceId===key);if(n)lead.push(n);}return [...lead,...sorted.filter(n=>!lead.some(l=>l.id===n.id))].slice(0,20);}
function mediaFor(n){return MEDIA_SNAPSHOTS[n.url]||n.image||NEWS_MEDIA[n.id]||null;}
function storyMedia(n){const m=mediaFor(n);return m?`<figure class="story-media"><img class="story-image" src="${m.method?e(m.src):n.kind==='rss'?'/api/reading/image?id='+encodeURIComponent(n.id):e(m.src)}" alt="${e(m.alt||n.title)}" loading="lazy" referrerpolicy="no-referrer"><figcaption><a class="media-credit" href="${e(m.sourceUrl||n.url)}" target="_blank" rel="noopener">${e(m.credit||n.publisher)}</a></figcaption></figure>`:'';}
function caseCover(c,local=false){
 const media=local?null:MEDIA_SNAPSHOTS[c.url]||c.image;
 const src=media?(media.method?media.src:'/api/reading/case-image?id='+encodeURIComponent(c.id)):'';
 return `<div class="case-cover ${local?'document-cover':!media?'image-unavailable':''}">${media?`<img class="case-cover-image" src="${e(src)}" alt="${e(media.alt||c.title)}" loading="lazy">`:local?`<span class="document-cover-icon" aria-hidden="true">${icon('file',64)}</span>`:''}<div><span class="pill mint">${e(local?'TÀI LIỆU CỦA BẠN':c.brand||c.publisher)}</span><h3>${e(c.title)}</h3></div></div>${media?`<p class="case-cover-credit"><a href="${e(c.url)}" target="_blank" rel="noopener">${e(media.credit||c.publisher)}</a></p>`:''}`;
}
function featureStory(n){const m=mediaFor(n),src=m?(m.method?m.src:n.kind==='rss'?'/api/reading/image?id='+encodeURIComponent(n.id):m.src):'';return `<article class="feature-story sourced-story panel news-focus-card ${m?'has-media':'text-story'}"><div class="news-cover">${m?`<img class="story-image" src="${e(src)}" alt="${e(m.alt||n.title)}" loading="lazy" referrerpolicy="no-referrer">`:''}<button class="icon-btn bookmark" data-action="save-story" data-id="${e(n.id)}" aria-label="${state.saved.includes(n.id)?'Unsave':'Save'} featured story" aria-pressed="${state.saved.includes(n.id)}">${icon(state.saved.includes(n.id)?'check':'bookmark',17)}</button><div class="news-cover-content"><span class="pill">${e(n.publisher)} · ${dateLabel(n.date,true)}</span><h3><button class="headline-link" data-action="story" data-id="${e(n.id)}">${e(n.title)}</button></h3></div></div>${m?`<p class="news-photo-credit"><a href="${e(m.sourceUrl||n.url)}" target="_blank" rel="noopener">${e(m.credit||n.publisher)}</a></p>`:''}<div class="feature-content"><p>${e(n.subtitle)}</p><button class="text-btn" data-action="story" data-id="${e(n.id)}">Đọc tin và nguồn ${icon('arrow',16)}</button></div></article>`;}
function newsDeck(items,scope){let index=items.findIndex(n=>n.id===newsSelection[scope]);if(index<0)index=0;const item=items[index];if(item)newsSelection[scope]=item.id;return `<div class="news-deck" data-news-scope="${scope}">${item?featureStory(item):emptyNews()}${items.length?`<div class="between news-navigation" role="group" aria-label="Chuyển bài báo"><button class="btn outline small-btn" data-action="news-prev" data-id="${scope}" ${items.length<2?'disabled':''} aria-label="Bài báo trước">← Trước</button><span class="tiny muted" role="status" aria-live="polite">Bài ${index+1} / ${items.length}</span><button class="btn outline small-btn" data-action="news-next" data-id="${scope}" ${items.length<2?'disabled':''} aria-label="Bài báo tiếp theo">Bài tiếp →</button></div>`:''}</div>`;}
function moveNews(scope,step){const items=scope==='saved'?allNews().filter(n=>state.saved.includes(n.id)):newsItems();if(!items.length)return;const current=Math.max(0,items.findIndex(n=>n.id===newsSelection[scope]));newsSelection[scope]=items[(current+step+items.length)%items.length].id;const deck=document.querySelector('[data-news-scope="'+scope+'"]');if(deck){const before=deck.getBoundingClientRect().top;deck.outerHTML=newsDeck(items,scope);const replacement=document.querySelector('[data-news-scope="'+scope+'"]');scrollBy({top:replacement.getBoundingClientRect().top-before,behavior:'instant'});replacement.querySelector('[data-action="news-'+(step>0?'next':'prev')+'"]').focus({preventScroll:true});}}
function storyCard(n){return `<article class="news-card panel sourced-story ${mediaFor(n)?'has-media':'text-story'}">${storyMedia(n)}<div class="story-copy"><div class="between"><span class="story-publisher">${e(n.publisher)}</span><button class="icon-btn" data-action="save-story" data-id="${e(n.id)}" aria-label="${state.saved.includes(n.id)?'Unsave':'Save'} ${e(n.title)}" aria-pressed="${state.saved.includes(n.id)}">${icon(state.saved.includes(n.id)?'check':'bookmark',15)}</button></div><button class="story-link" data-action="story" data-id="${e(n.id)}"><h3>${e(n.title)}</h3></button><p>${e(n.subtitle)}</p><div class="between news-meta"><time datetime="${e(n.date)}">${dateLabel(n.date)}</time><button class="icon-btn" data-action="story" data-id="${e(n.id)}" aria-label="Read ${e(n.title)}">${icon('arrowUp',14)}</button></div></div></article>`;}
function timeLabel(value){return value&&Number.isFinite(Date.parse(value))?new Intl.DateTimeFormat('vi-VN',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Bangkok'}).format(new Date(value)):'chưa có lần cập nhật thành công';}
function readingStatusView(){const failed=reading.sources?.filter(s=>s.error)||[];return `<div class="reading-status" role="status"><div><strong>${readingStatus==='loading'?'Đang kiểm tra tin mới…':readingError||reading.degraded?'Đang dùng bản gần nhất ở các nguồn tạm lỗi':'Tin từ nguồn RSS chính thức'}</strong><p>Cập nhật thành công: ${e(timeLabel(reading.updatedAt))} · Kiểm tra mỗi 15 phút khi mở trang.</p>${readingError?`<p>${e(readingError)}</p>`:''}${failed.length?`<p>Nguồn tạm lỗi: ${failed.map(s=>e(s.publisher)).join(', ')}. Các phần học vẫn hoạt động.</p>`:''}</div><button class="btn outline small-btn" data-action="refresh-news" ${readingBusy?'disabled':''}>${icon('refresh',14)} ${readingBusy?'Đang tải':'Làm mới'}</button></div>`;}
function newsStream(){return `<div class="between section-heading"><div><h2>Market Pulse <span class="pill mint">RSS · CÓ NGUỒN</span></h2><p class="section-sub">Một bản tin mỗi lần, đọc theo nhịp của bạn.</p></div><a href="#news" class="text-btn">Market Pulse ${icon('arrow',14)}</a></div>${readingStatusView()}${newsDeck(newsItems(),'home')}<p class="source-note">Ngày trên mỗi bài là ngày xuất bản. Ảnh và liên kết dẫn về đúng nguồn bài báo.</p>`;}
function casePanel(){const c=dailyCase(reading.caseStudies,caseOffset),sections=localCaseSections(state.documents);const local=sections.find(s=>s.id===localCaseId)||sections[0];return `<section id="case-study-panel" class="case-panel panel"><div class="between"><div><div class="eyebrow muted">MỖI NGÀY MỘT GÓC NHÌN</div><h2>Case study hôm nay</h2></div>${icon('book',22)}</div><p class="source-note">${e(todayKey())} · Bài đọc luân phiên theo ngày, giữ nguyên bối cảnh chiến dịch.</p><div class="case-tabs" role="group" aria-label="Nguồn case study"><button class="${caseMode==='web'?'active':''}" data-action="case-tab" data-id="web" aria-pressed="${caseMode==='web'}">Từ web</button><button class="${caseMode==='documents'?'active':''}" data-action="case-tab" data-id="documents" aria-pressed="${caseMode==='documents'}">Tài liệu của bạn</button></div>${caseMode==='documents'?sections.length?`<label class="small" for="case-document-section">Chọn trích đoạn đã đọc được</label><select id="case-document-section">${sections.map(s=>`<option value="${e(s.id)}" ${s.id===local.id?'selected':''}>${e(s.title)} · ${s.page}${s.candidate?' · có từ khóa tình huống':''}</option>`).join('')}</select><span class="pill blue">TRÍCH ĐOẠN NGUỒN · CHƯA PHẢI PHÂN TÍCH TỰ ĐỘNG</span>${caseCover(local,true)}<p class="case-excerpt">${e(local.text.slice(0,420))}</p><button class="btn primary" data-action="case-open" data-id="${e(local.id)}">Đọc trích đoạn ${icon('arrow',14)}</button>`:`<div class="case-empty"><h3>Đọc case từ tài liệu của bạn</h3><p>Tải PDF, DOCX hoặc PPTX, rồi trích xuất trang/mục muốn đọc. Chỉ phần đọc được mới xuất hiện ở đây; tài liệu không gửi đến dịch vụ AI.</p><button class="btn outline" data-action="upload">Thêm tài liệu ${icon('upload',14)}</button></div>`:c?`${caseCover(c)}<p class="case-excerpt">${e(c.summary)}</p><p class="source-note">${e(c.publisher)}${c.campaignPeriod?' · '+e(c.campaignPeriod):''}<br>${c.date?'Xuất bản '+dateLabel(c.date):'Ngày xuất bản chưa được nguồn xác nhận.'}<br>Thư viện kiểm tra: ${e(timeLabel(reading.caseUpdatedAt))}</p><button class="btn primary" data-action="case-open" data-id="${e(c.id)}">${state.caseRead.includes(c.id)?'Đọc lại case study':'Đọc case study'} ${icon('arrow',14)}</button><div class="between case-navigation"><button class="text-btn" data-action="case-prev" aria-label="Case study trước">← Trước</button><span class="tiny muted">${reading.caseStudies.length} bài trong thư viện</span><button class="text-btn" data-action="case-next">Bài tiếp →</button></div>`:`<p class="source-note">Đang tải thư viện case study có nguồn. Chọn Làm mới nếu kết nối bị gián đoạn.</p>`}<p class="source-note">${state.caseRead.length} case đã đánh dấu đọc · Không cộng vào mức độ hiểu môn học.</p></section>`;}
function refreshCasePanel(){const panel=$('#case-study-panel');if(panel)panel.outerHTML=casePanel();}
function refreshReadingPanels(){
 if(!reference)return;
 const top=($('.topbar')?.getBoundingClientRect().bottom||78)+20;
 const anchor=[...document.querySelectorAll('[data-section]')].find(el=>el.getBoundingClientRect().top<=top&&el.getBoundingClientRect().bottom>top);
 const before=anchor?.getBoundingClientRect().top;
 const focused=document.activeElement,action=focused?.dataset?.action,id=focused?.dataset?.id;
 if($('#daily-news-content'))$('#daily-news-content').innerHTML=newsStream();
 if($('#news'))$('#news').innerHTML=newsPage();
 if($('#saved'))$('#saved').innerHTML=newsPage(true);
 refreshCasePanel();
 if(anchor)scrollTo({top:scrollY+anchor.getBoundingClientRect().top-before,behavior:'instant'});
 if(action&&!focused.isConnected){const replacement=[...document.querySelectorAll('[data-action]')].find(el=>el.dataset.action===action&&el.dataset.id===id);replacement?.focus({preventScroll:true});}
}
async function updateReading(force=false){if(readingBusy)return;readingBusy=true;readingStatus='loading';if(force)refreshReadingPanels();try{reading=await fetchEdition();readingStatus='ready';readingError='';}catch(error){readingStatus='error';readingError='Không tải được tin mới. Đang giữ bản gần nhất; chọn Làm mới để thử lại.';}finally{readingBusy=false;refreshReadingPanels();}}
function openCase(id){const local=localCaseSections(state.documents).find(s=>s.id===id),c=local||reading.caseStudies.find(c=>c.id===id);if(!c)return toast('Bài đọc không còn trong thư viện. Hãy làm mới hoặc chọn bài khác.');const source=local?`<p class="source-note">${e(local.sourceLabel)}</p><button class="text-btn" data-action="case-source-page" data-id="${e(local.documentId)}" data-page="${local.page}">Mở trang/mục nguồn ${icon('arrowUp',14)}</button>`:`<p class="source-note">${e(c.publisher)} · ${e(c.campaignPeriod||'Bối cảnh chiến dịch: xem nguồn gốc')}<br>Kiểm tra nguồn: ${e(timeLabel(c.checkedAt))}</p><a href="${e(c.url)}" class="btn outline" target="_blank" rel="noopener">Đọc case đầy đủ tại nguồn ${icon('arrowUp',14)}</a>`;openModal('Đọc và suy ngẫm',`<span class="pill blue">${local?'TÀI LIỆU TRÊN TRÌNH DUYỆT':'CASE STUDY CÓ NGUỒN'}</span><h3 class="story-title">${e(c.title)}</h3>${source}<h3>${local?'Trích đoạn nguyên văn':'Tóm lược có nguồn'}</h3><p class="case-body">${e(local?local.text.slice(0,12000):c.summary)}</p><h3>Câu hỏi để tự phân tích</h3><p>${e(c.question||'Bối cảnh, vấn đề, lựa chọn chiến lược và bằng chứng kết quả nằm ở đâu trong nguồn? Điểm nào chưa đủ dữ liệu để kết luận?')}</p><p class="source-note">Câu hỏi là gợi ý học tập. Số liệu kết quả trong bài gốc cần được quy về nguồn công bố; không coi là xác nhận độc lập.</p><label class="small" for="case-reflection">Suy ngẫm của bạn</label><textarea id="case-reflection" placeholder="Insight, chiến lược, bằng chứng và giới hạn…">${e(state.notes['case:'+id]||'')}</textarea><div class="actions"><button class="btn outline" data-action="case-save-note" data-id="${e(id)}">Lưu suy ngẫm</button><button class="btn primary" data-action="case-read" data-id="${e(id)}">${state.caseRead.includes(id)?'Đã đọc':'Đánh dấu đã đọc'}</button></div>`);}

function bookVolume(c){
 const cover=COURSE_COVERS[c.id];
 return `<div class="book-stage"><div class="book-volume" style="--cover-ratio:${cover?cover.width+'/'+cover.height:'3/4'};--book-edge:${cover?.edge||'#315477'}"><div class="book-face">${cover?`<img class="book-cover-image" src="${e(cover.src)}" alt="${e(coverAlt(c))}" loading="lazy" width="${cover.width}" height="${cover.height}">`:`<div class="book-placeholder"><span>YOUR COLLECTION</span><strong>${e(c.name)}</strong><span>Add a document to begin</span></div>`}</div><span class="book-pages" aria-hidden="true"></span><span class="book-back" aria-hidden="true"></span></div></div>`;
}
function home(){const m=metrics(state,allCards());return `<div class="welcome"><div><div class="eyebrow muted">A LITTLE NEWS. A LITTLE KNOWLEDGE. A LITTLE YOU.</div><h1>Stay curious, <span class="serif" style="color:var(--blue)">Zin.</span> ${icon('spark',25)}</h1><p>Your world, your books, and your next little step — all in one place.</p></div><div class="welcome-actions"><button class="btn primary" data-action="start">${icon('play',14)} Start study session</button><span class="date-chip">${icon('calendar',16)}${new Intl.DateTimeFormat('en',{weekday:'long',day:'numeric',month:'long',timeZone:'Asia/Bangkok'}).format(new Date())}</span></div></div><div class="home-grid"><section id="daily-news-content">${newsStream()}</section><aside class="home-aside">${casePanel()}<section class="focus-panel panel"><span class="focus-decoration">${icon('spark',33)}</span><div class="eyebrow" style="color:var(--blue-text)">MAKE ROOM FOR A LITTLE GROWTH</div><h3>Your next small step</h3><p>${m.due?`${m.due} review ${m.due===1?'card is':'cards are'} ready. Give your memory a gentle refresh.`:'Start with a short marketing lesson. Understand an idea, then try recalling it.'}</p><div class="duration" role="group" aria-label="Study time budget">${[5,15,25].map(n=>`<button class="${state.duration===n?'active':''}" data-action="duration" data-id="${n}" aria-pressed="${state.duration===n}">${n} min</button>`).join('')}</div><button class="btn primary" data-action="start">${icon('play',14)} Start study session ${icon('arrow',15)}</button><p class="tiny" style="margin-top:10px;text-align:center">A warm-up is optional. Your pace is enough.</p></section><section class="week-panel panel"><div class="between"><h3 style="font-size:12px">This week, in little steps</h3>${icon('chart',17)}</div>${weeklyChart()}<p class="tiny muted">${state.attempts.length?'Review attempts, counted separately from lesson completion.':'Your first review will start the story. No pressure to keep a streak.'}</p></section></aside></div>`;}
function pageHead(kicker,title,desc,button=''){return `<div class="between page-head"><div><div class="eyebrow muted">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${button}</div>`;}
function bookshelfTile(c){const cover=COURSE_COVERS[c.id];return `<button class="book-tile" data-action="course" data-id="${e(c.id)}" aria-label="Open ${e(c.name)}: ${e(c.books?.[0]?.title||'personal collection')}">${bookVolume(c)}<div class="book-meta"><span class="book-course-name">${e(c.name)}</span><h3>${e(c.books?.[0]?.title||c.name)}</h3><p>${e(c.books?.[0]?.authors?.join(', ')||'Your personal collection')}</p><span class="pill ${c.current?'blue':'mint'}">${cover?.kind==='slides'?'COURSE SLIDES':c.current?'CURRENT SEMESTER':`${c.books?.length||0} reference ${c.books?.length===1?'book':'books'}`}</span></div></button>`;}
function library(){const courses=allCourses().filter(c=>(libraryTerm==='all'||c.current)&&`${c.name} ${c.books?.map(b=>b.title+' '+b.authors.join(' ')).join(' ')}`.toLowerCase().includes(libraryFilter.toLowerCase()));return `${pageHead('THE BOOKSHELF','Good books. Bigger ideas.','Your real course books, ready for their next chapter.',`<button class="btn primary" data-action="upload">${icon('plus',16)} Add document</button>`)}<div class="toolbar"><input id="library-search" type="text" value="${e(libraryFilter)}" placeholder="Search courses, books or authors" aria-label="Search bookshelf"><select id="library-term" aria-label="Filter courses"><option value="all" ${libraryTerm==='all'?'selected':''}>All courses</option><option value="current" ${libraryTerm==='current'?'selected':''}>Current semester</option></select><button class="btn outline" data-action="new-course">${icon('plus',15)} New course</button></div><div class="bookshelf">${courses.map(bookshelfTile).join('')}</div>${courses.length?'':`<div class="empty"><h3>No books found</h3><p>Try a shorter title, another author, or all courses.</p></div>`}<div class="info-strip">${icon('info',17)}<div>Original covers from your local course documents. Logistics uses its original title slide, labelled Course slides. Mỗi môn có tài liệu gốc trong kho riêng tư và chỗ gắn website học riêng. Bản tải lên từ trình duyệt vẫn lưu trên thiết bị.</div></div>`;}
function lessonRows(lessons){return `<div class="lesson-list">${lessons.map((l,i)=>`<article class="lesson-row panel"><span class="lesson-number">${String(i+1).padStart(2,'0')}</span><div><span class="eyebrow muted" style="font-size:8px">${e(l.chapter)}</span><h3>${e(l.title)}</h3><p>${state.completed.includes(l.id)?'Studied · recall practice still matters':`${l.questions.length} recall prompts · source pages included`}</p></div><a href="#lesson/${l.id}" class="btn outline small-btn">${state.completed.includes(l.id)?'Revisit':'Open lesson'} ${icon('arrow',14)}</a></article>`).join('')}</div>`;}

function coursePortal(c){const url=state.courseLinks[c.id];return `<section class="panel panel-pad course-portal"><span class="pill blue">WEBSITE HỌC RIÊNG</span><h2>Không gian học · ${e(c.name)}</h2><p class="muted small">${url?'Website môn đã được liên kết. Mở trong tab riêng để học theo chương.':'Chưa có website môn. Khi xây xong, gắn địa chỉ tại đây.'}</p><div class="actions">${url?`<a class="btn primary" href="${e(url)}" target="_blank" rel="noopener noreferrer">Vào website môn học ${icon('arrowUp',15)}</a>`:''}<button class="btn ${url?'outline':'primary'}" data-action="course-link" data-id="${e(c.id)}">${url?'Sửa liên kết':'Gắn link website'} ${icon('plus',14)}</button></div>${url?`<p class="source-note course-url">${e(url)}</p>`:''}<p class="source-note">Tài liệu và tiến độ trong Studio chưa tự đồng bộ sang website khác.</p></section>`;}
function materialRow(c,b){const m=materials.find(x=>x.id===b.id),available=!!materialAvailability[b.id];return `<div class="doc-row source-material">${icon('book',25)}<div><strong>${e(b.title)}</strong><p>${e(b.authors.join(', '))}</p><p>${b.pages?b.pages+' trang · ':''}${e(b.edition||'Bản gốc đã đối chiếu')}${m?' · '+(m.bytes/1048576).toFixed(1)+' MB':''}</p><p class="tiny">${available?'Đã gắn tài liệu gốc · Kho riêng tư':materialStatus==='loading'?'Đang kiểm tra tài liệu…':'Chưa kết nối được bản gốc; có thể gắn bản trên máy.'}</p>${b.legacy?'<p class="source-note">Slide .ppt: tải về để mở bằng PowerPoint; chưa hỗ trợ đọc trực tiếp.</p>':''}</div><div class="material-actions">${available?`${!b.legacy?`<a class="btn primary small-btn" href="/api/materials/${e(b.id)}" target="_blank" rel="noopener">Đọc PDF gốc ${icon('arrowUp',13)}</a>`:''}<a class="btn outline small-btn" href="/api/materials/${e(b.id)}?download=1" target="_blank" rel="noopener">Tải bản gốc ${icon('download',13)}</a>`:''}${!b.legacy?`<button class="text-btn" data-action="upload" data-id="${e(c.id)}">Gắn bản trên máy</button>`:''}</div></div>`;}
function courseLinkDialog(id){const c=allCourses().find(c=>c.id===id);if(!c)return;openModal('Website học · '+c.name,`<p>Gắn website riêng sau khi đã xây xong. Liên kết lưu trên trình duyệt này và có trong bản sao lưu tiến độ.</p><form id="course-link-form" data-id="${e(id)}"><div class="form-field"><label for="course-site-url">Địa chỉ website môn (HTTPS)</label><input id="course-site-url" name="url" type="url" maxlength="2000" placeholder="https://…" value="${e(state.courseLinks[id]||'')}"></div><p class="source-note">Để trống và lưu để bỏ liên kết. Tài liệu, chatbot và tiến độ cần được cấu hình trong website môn; Studio chưa gửi dữ liệu sang đó.</p><div id="course-link-error" class="error" role="status"></div><button class="btn primary" type="submit">Lưu liên kết</button></form>`);}
async function loadMaterials(){try{const [catalog,status]=await Promise.all([fetch('/data/materials.json'),fetch('/api/materials')]);if(!catalog.ok||!status.ok)throw Error();materials=await catalog.json();const data=await status.json();materialAvailability=Object.fromEntries(data.items.map(m=>[m.id,m.available]));materialStatus='ready';}catch{materialStatus='error';}if(reference){contentDirty=true;render();}}

function coursePage(id){const c=allCourses().find(c=>c.id===id);if(!c)return notFound();const docs=state.documents.filter(d=>d.courseId===id),lessons=courseLessons(id),cards=state.cards.filter(c=>c.courseId===id);return `${pageHead('YOUR COURSE COLLECTION',e(c.name),c.current?'Year 2 · Semester 1. Results are pending; learning can begin now.':'Your reference books and a space to make knowledge stick.',`<button class="btn primary" data-action="upload" data-id="${c.id}">${icon('plus',16)} Add document</button>`)}<div class="two-col"><div class="stack">${coursePortal(c)}<section class="panel panel-pad"><div class="between"><h2>Reference shelf</h2><span class="pill">TÀI LIỆU MÔN</span></div>${(c.books||[]).map(b=>materialRow(c,b)).join('')||'<p class="muted small">Môn mới đang chờ tài liệu đầu tiên.</p>'}<p class="source-note">Bản gốc nằm trong kho riêng tư của Studio. Bản gắn trên máy và ghi chú giữ riêng trên trình duyệt; thêm phiên bản không xoá lịch sử học.</p></section><section><div class="between section-heading"><h2>Learn visually</h2><span class="pill">${lessons.length} starter lessons</span></div>${lessons.length?lessonRows(lessons):`<div class="empty"><h3>A clean page for your next idea.</h3><p>Attach a document, select a section and create a source-linked recall card.</p><button class="btn outline" data-action="upload" data-id="${id}">Add your first document</button></div>`}</section><section class="panel panel-pad"><h2>Attached documents</h2>${docs.length?docs.map(d=>`<div class="doc-row">${icon('file',23)}<div><strong>${e(d.name)}</strong><p>${d.type.toUpperCase()} · ${d.pages} ${d.type==='pptx'?'slides':d.type==='docx'?'text section':'pages'} · Added ${dateLabel(d.added,true)}</p><p>${d.sections.length} sections extracted · version ${e(d.id.slice(0,8))}</p></div><button class="btn outline small-btn" data-action="reader" data-id="${d.id}">Read ${icon('arrow',13)}</button></div>`).join(''):'<p class="muted small section-space">No local copy attached yet.</p>'}</section>${cards.length?`<section class="panel panel-pad"><h2>Your review cards</h2>${cards.map(c=>`<div class="check-row"><div class="check-copy"><strong>${e(c.question)}</strong><small>${e(c.sourceLabel)}</small></div><button class="text-btn" data-action="edit-card" data-id="${c.id}">Edit</button></div>`).join('')}<button class="btn primary section-space" data-action="practice-course" data-id="${id}">Practice these cards</button></section>`:''}</div><aside class="stack" style="align-content:start"><img class="${hasCover(c)?'course-detail-cover':''}" src="${e(coverImage(c))}" style="border-radius:18px;width:100%" alt="${e(coverAlt(c))}"><section class="panel panel-pad"><h3>A little learning loop</h3><p class="muted small" style="line-height:2;margin-top:14px">1. Read a manageable section.<br>2. Connect the ideas.<br>3. Try to explain them from memory.<br>4. Check, then come back later.</p></section></aside></div>`;}
function study(){const cards=allCards(),m=metrics(state,cards),queue=reviewQueue(cards,state);return `${pageHead('THE STUDY ROOM','Small sessions. Real understanding.','Read, connect, recall. Give each idea a chance to become your own.',`<button class="btn primary" data-action="start">${icon('play',15)} Start study session</button>`)}<div class="stat-grid"><div class="stat-card panel"><span class="eyebrow muted">LESSONS STUDIED</span><strong>${state.completed.filter(x=>LESSONS.some(l=>l.id===x)).length} <span class="small muted">/ ${LESSONS.length}</span></strong><p>Starter lessons, not whole courses</p></div><div class="stat-card panel"><span class="eyebrow muted">RECALL PRACTICE</span><strong>${m.attempts}</strong><p>${m.independent} self-assessed independent answers</p></div><div class="stat-card panel"><span class="eyebrow muted">READY TO REVIEW</span><strong>${m.due}</strong><p>${m.newCards} new cards to explore</p></div><div class="stat-card panel"><span class="eyebrow muted">SPACED EVIDENCE</span><strong>${m.evidence||'—'}</strong><p>${m.evidence?'Cards with repeated independent recall':'Insufficient data · keep exploring'}</p></div></div><div class="two-col"><div class="stack"><section><div class="section-heading"><h2>Begin with an idea</h2><p class="section-sub">Source-checked lessons from Marketing: An Introduction.</p></div>${lessonRows(LESSONS)}</section><section class="panel panel-pad"><div class="between"><h2>Your review queue</h2><button class="text-btn" data-action="method">How it works ${icon('info',14)}</button></div>${queue.length?queue.slice(0,7).map(c=>`<div class="check-row"><span class="pill ${state.reviews[c.id]?'amber':'blue'}">${state.reviews[c.id]?'DUE':'NEW'}</span><div class="check-copy"><strong>${e(c.question)}</strong><small>${e(courseName(c.courseId))}</small></div></div>`).join(''):'<p class="muted small section-space">You’re up to date. Your next review will appear here.</p>'}</section><section class="panel panel-pad"><h2>Recent practice</h2>${state.attempts.length?state.attempts.slice(-8).reverse().map(a=>`<div class="check-row"><span class="pill ${a.result==='again'?'amber':'mint'}">${a.result==='again'?'Reinforce':a.result==='hard'?'With effort':'Recalled'}</span><div class="check-copy"><strong>${e(cards.find(c=>c.id===a.cardId)?.question||'Archived card')}</strong><small>${dateLabel(a.at)} · ${a.hintUsed?'Hint used':'No hint'} · Self-assessed</small></div></div>`).join(''):'<p class="muted small section-space">No attempts yet. Your first answer is a good place to start.</p>'}</section></div><aside class="stack" style="align-content:start"><section class="panel panel-pad"><h3>Your week in reviews</h3>${weeklyChart()}<p class="small muted">Activity shows practice attempts. Reading and news never raise a mastery score.</p></section><section class="panel panel-pad"><h3>What needs another look?</h3>${state.attempts.some(a=>a.result==='again')?[...new Set(state.attempts.filter(a=>a.result==='again').map(a=>a.cardId))].slice(0,5).map(id=>`<p class="small muted section-space">${e(cards.find(c=>c.id===id)?.question||'Archived card')}</p>`).join(''):'<p class="small muted section-space">No missed concepts recorded yet. This space will use your own practice results.</p>'}</section><section class="panel panel-pad"><h3>Coming up</h3>${Object.values(state.reviews).length?Object.values(state.reviews).sort((a,b)=>a.nextReview.localeCompare(b.nextReview)).slice(0,5).map(r=>`<div class="check-row"><div class="check-copy"><strong>${e(cards.find(c=>c.id===r.cardId)?.question||'Archived card')}</strong><small>${dateLabel(r.nextReview)} · ${r.interval} day interval</small></div></div>`).join(''):'<p class="small muted section-space">Your next-review dates appear after your first practice.</p>'}</section></aside></div>`;}
function lessonPage(id){const l=LESSONS.find(l=>l.id===id);if(!l)return notFound();return `${pageHead(e(l.chapter),'Make the idea click.',e(courseName(l.courseId)))}<div class="lesson-layout"><article class="panel lesson-main"><span class="pill blue">SOURCE-BASED LESSON</span><h2>${e(l.title)}</h2><p>${e(l.subtitle)}</p><h3>By the end, you can…</h3><p>${e(l.objective)}</p><h3>The idea at a glance</h3><ul>${l.points.map(p=>`<li>${e(p)}</li>`).join('')}</ul><h3>Connect the dots</h3><div class="concept-flow">${l.nodes.map(([a,b])=>`<div class="concept-node"><strong>${e(a)}</strong><span>${e(b)}</span></div>`).join('')}</div><p class="tiny">${e(l.relation)}</p><details><summary>Read the connections as a list</summary><ol>${l.nodes.map(([a,b])=>`<li><strong>${e(a)}:</strong> ${e(b)}</li>`).join('')}</ol><a href="assets/marketing-source-pages.pdf#page=${l.pdfPage}" target="_blank" rel="noopener">View original source pages ${icon('arrowUp',12)}</a></details><div class="example"><span class="pill mint">HYPOTHETICAL SCENARIO</span><h3 style="margin-top:8px">Try it in the real world</h3><p>${e(l.example)}</p></div><details><summary>A common mix-up</summary><p>${e(l.misconception)}</p></details><h3>Try explaining it without looking</h3><ul>${l.questions.map(q=>`<li>${e(q.question)}</li>`).join('')}</ul><div class="divider"></div><div class="between" style="flex-wrap:wrap"><button class="btn outline" data-action="complete-lesson" data-id="${id}">${icon(state.completed.includes(id)?'check':'book',16)} ${state.completed.includes(id)?'Marked as studied':'Mark as studied'}</button><button class="btn primary" data-action="practice-lesson" data-id="${id}">Try active recall ${icon('arrow',15)}</button></div><p class="source-note">Marking a lesson as studied tracks reading, not understanding.</p></article><aside class="stack" style="align-content:start"><section class="panel panel-pad"><div class="eyebrow muted">ON YOUR DESK</div><h3 style="margin:14px 0">Marketing: An Introduction</h3><p class="small muted">Gary Armstrong, Philip Kotler & Marc Oliver Opresnik</p><p class="source-note">${e(l.source)}</p><a class="btn outline section-space" href="assets/marketing-source-pages.pdf#page=${l.pdfPage}" target="_blank" rel="noopener">Open source ${icon('arrowUp',14)}</a><p class="source-note">The included extract contains original PDF pages 31, 32, 36 and 37, in that order. Notes are paraphrased; the café examples are hypothetical.</p></section><section class="panel panel-pad"><h3>Put it in your own words</h3><div class="form-field"><label class="small muted" for="lesson-note">Your personal notes</label><textarea id="lesson-note" placeholder="One idea, a question, or an example…">${e(state.notes[id]||'')}</textarea></div><button class="btn outline" data-action="save-note" data-id="${id}">Save note</button></section></aside></div>`;}
function emptyNews(){return `<div class="empty"><h3>A quieter feed.</h3><p>You have hidden all stories in this reading edition.</p><button class="btn outline" data-action="reset-news">Show all stories again</button></div>`;}
function newsPage(saved=false){const items=saved?allNews().filter(n=>state.saved.includes(n.id)):newsItems();return `${pageHead(saved?'YOUR READING LIST':'MARKET PULSE',saved?'Good ideas, kept close.':'Tin mới, góc nhìn rộng hơn.',saved?'Những bài bạn đã lưu trên trình duyệt này.':'Mỗi lần hiển thị một bài. Dùng Trước / Bài tiếp để chuyển tin.')}${saved?'':readingStatusView()}${items.length?newsDeck(items,saved?'saved':'news'):saved?'<div class="empty"><h3>Chưa có bài đã lưu.</h3><a href="#news" class="btn outline">Khám phá tin mới</a></div>':emptyNews()}${!saved&&state.hidden.length?'<button class="btn outline section-space" data-action="reset-news">Hiện lại tin đã ẩn</button>':''}<p class="source-note">${state.read.length} bản tin đã đánh dấu đọc · Đọc tin không làm tăng mức độ hiểu bài.</p>`;}
function settings(){return `${pageHead('STUDIO SETTINGS','Make yourself at home.','A quiet space that remembers your preferences on this browser.')}<div class="two-col"><div class="stack"><section class="panel panel-pad"><h2>Appearance</h2><p class="muted small section-space">A bright desk or a late-night reading nook.</p><div class="settings-row"><button class="btn outline" data-action="set-theme" data-id="light">${icon('sun')} Light</button><button class="btn outline" data-action="set-theme" data-id="dark">${icon('moon')} Dark</button></div></section><section class="panel panel-pad"><h2>Your data belongs with you</h2><p class="muted small section-space">Progress, notes and preferences are stored on this browser. Uploaded documents stay in this browser’s local storage; they are never sent to an AI service. Clearing browser data or using another device will not carry them over.</p><div class="settings-row"><button class="btn primary" data-action="backup">${icon('download',16)} Export progress backup</button><button class="btn outline" data-action="import-backup">${icon('upload',16)} Import backup</button></div><p class="source-note">Backups include notes, extracted text, cards and reviews. They do not include original document files; keep those separately and reattach them after restoring. Import merges records and preserves existing local edits. Store your backup privately.</p>${storageError?'<button class="btn outline section-space" data-action="raw-backup">Download existing unreadable data</button>':''}</section><section class="panel panel-pad"><h2>How progress works</h2><p class="muted small section-space">Reading completion, self-assessed recall, evidence across spaced reviews and news activity are separate. Nothing is awarded simply for opening a page.</p><button class="text-btn" data-action="method">Read the review method ${icon('arrow',14)}</button></section></div><aside class="panel panel-pad" style="align-self:start"><h3>About this little studio</h3><p class="muted small section-space">English interface, your navy, blue and gold palette and your cat collection. The bookshelf takes inspiration from the calm, inviting reading experience you liked at Khoaverse.</p><p class="muted small section-space">Notion data: a checked snapshot from 16 November 2026. Changes here do not edit Notion. The full local book catalog is referenced; attach individual documents to read them.</p><p class="muted small section-space">Supported: text PDFs, DOCX text and PPTX slide text. Image-only pages need OCR elsewhere. Automatic AI synthesis is not connected. News refreshes from official RSS; uploaded documents stay on this browser.</p><a href="https://khoaverse.fun/" target="_blank" rel="noopener" class="text-btn section-space">Design inspiration ${icon('arrowUp',13)}</a></aside></div>`;}
function notFound(){return '<div class="empty"><h1>This page wandered off.</h1><p>Your books and progress are still here.</p><a href="#home" class="btn primary">Back to The Daily</a></div>';}
document.addEventListener('error',event=>{if(!(event.target instanceof HTMLImageElement))return;if(event.target.classList.contains('story-image')){event.target.closest('.sourced-story')?.classList.add('media-failed');event.target.remove();}if(event.target.classList.contains('case-cover-image')){event.target.closest('.case-cover')?.classList.add('image-unavailable');event.target.remove();}},true);
function render(){
 [route='home',param='']=location.hash.slice(1).split('/');if(!route)route='home';
 if(Object.hasOwn(detailViews,route))detailViews[route]=route+(param?'/'+param:'');
 // Preserve drafts and the viewport when a control updates another section.
 const focused=document.activeElement,focusId=focused?.id,selection=focused?.selectionStart;
 const drafts=['lesson-note','doc-note'].map(id=>{const el=document.getElementById(id);return el?{id,value:el.value,context:el.closest('[data-detail-path]')?.dataset.detailPath}:null;}).filter(Boolean);
 const topbar=$('.topbar')?.getBoundingClientRect().bottom||80;
 const anchor=[...document.querySelectorAll('[data-section]')].find(el=>el.getBoundingClientRect().top<=topbar&&el.getBoundingClientRect().bottom>topbar);
 const oldY=scrollY,anchorId=anchor?.id,anchorTop=anchor?.getBoundingClientRect().top;
 const wrap=(key,body,path='')=>`<section id="${key}" class="studio-section ${path?'detail-section':''}" tabindex="-1" aria-label="${e(sectionNames[key]||({course:'Course collection',reader:'Reading Room',lesson:'Lesson',practice:'Recall session'})[key])}" data-section="${detailParents[key]||key}" ${path?`data-detail-path="${e(path)}"`:''}>${body}</section>`;
 const detail=key=>{
  const path=detailViews[key];if(!path)return '';
  const savedParam=param;param=path.split('/')[1]||'';
  const body=({course:()=>coursePage(param),reader:readerPage,lesson:()=>lessonPage(param),practice:practicePage})[key]();
  param=savedParam;return wrap(key,body,path);
 };
 shell(wrap('home',home())+wrap('library',library())+detail('course')+detail('reader')+wrap('study',study())+detail('lesson')+detail('practice')+wrap('news',newsPage())+wrap('saved',newsPage(true))+wrap('settings',settings()));
 for(const draft of drafts){const el=document.getElementById(draft.id);if(el?.closest('[data-detail-path]')?.dataset.detailPath===draft.context)el.value=draft.value;}
 if(detailViews.reader&&reader)drawReader();
 const restored=document.getElementById(focusId);
 if(restored){restored.focus({preventScroll:true});if(typeof selection==='number'&&restored.setSelectionRange&&['text','search','textarea'].includes(restored.type))restored.setSelectionRange(selection,selection);}
 const newAnchor=document.getElementById(anchorId);
 scrollTo({top:newAnchor?scrollY+newAnchor.getBoundingClientRect().top-anchorTop:oldY,behavior:'instant'});
 setActiveSection(route);
 contentDirty=false;
}

function openModal(title,body){lastFocus=document.activeElement;modal.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${e(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close',20)}</button></div><div class="dialog-body">${body}</div>`;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();lastFocus?.focus?.();}
modal.addEventListener('click',ev=>{if(ev.target===modal){const r=modal.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeModal();}});
function story(id){const n=allNews().find(n=>n.id===id);if(!n)return;rememberStory(n);openModal('Đọc tin có nguồn',`<span class="pill blue">${e(n.publisher)}</span><h3 class="story-title">${e(n.title)}</h3><p class="source-note">Xuất bản ${dateLabel(n.date)}${n.kind==='rss'?' · Nội dung tóm tắt từ RSS của nhà xuất bản.':' · Bản lưu từ phiên bản trước.'}</p><h3>Nội dung từ nguồn</h3><p>${e(n.subtitle||n.happened)}</p><h3>Góc tự suy ngẫm</h3><p>${e(n.topic==='Thế giới'?'Những thông tin nào đã được xác nhận? Có thể có tác động nào đến chuỗi cung ứng, nhu cầu hoặc hoạt động kinh doanh? Đây là câu hỏi gợi mở, chưa phải kết luận.':n.topic==='Marketing'?'Thay đổi này liên quan đến kênh truyền thông, đo lường hay trải nghiệm khách hàng? Đọc thông báo gốc để kiểm tra điều kiện áp dụng.':'Sự kiện này có thể liên quan đến khách hàng, chi phí hoặc môi trường kinh doanh như thế nào? Đây là câu hỏi gợi mở; không phải dự báo hay khuyến nghị đầu tư.')}</p><p class="source-note">Tách biệt phần tin từ nguồn và câu hỏi học tập. Đọc bài gốc để xem đầy đủ bối cảnh; thông tin nhạy cảm đang phát triển cần được đối chiếu thêm nguồn.</p><div class="actions"><a href="${e(n.url)}" class="btn primary" target="_blank" rel="noopener">Đọc bài gốc ${icon('arrowUp',14)}</a><button class="btn outline" data-action="mark-read" data-id="${e(n.id)}">${state.read.includes(n.id)?'Marked as read':'Mark as read'}</button><button class="text-btn" data-action="hide-story" data-id="${e(n.id)}">Hide this story</button></div>`);}

function method(){openModal('A gentler review rhythm',`<p>Each card keeps its own answer history, help used and next review date. This is a transparent heuristic schedule based on your self-assessment, not a prediction of your memory.</p><h3>How the interval changes</h3><p>Independent recall progresses through 1, 3, 7, 14 and 30 days. An interval only advances when the next independent attempt is at least 24 hours after the last one. Same-day practice does not advance the stage.</p><p style="margin-top:14px">“Needs another look” returns to 1 day. A hint or an answer seen before recall also limits the next interval to 1 day. “With effort” reduces the stage and caps the interval at 3 days.</p><h3>What counts as evidence?</h3><p>Two independent, self-assessed successful recalls on separate days are shown as spaced evidence. This is not an official mastery score. Opening a lesson, reading news or completing a checklist never counts as evidence of understanding.</p><h3>A manageable session</h3><p>A 5 / 15 / 25 minute budget selects up to 3 / 7 / 12 due or new cards. This is a planning estimate, not a timer. Due cards come first. There is no penalty for taking a day off.</p>`);}
function startSession(onlyLesson=null,onlyCourse=null){
 let cards=allCards();if(onlyLesson)cards=cards.filter(c=>c.lessonId===onlyLesson);if(onlyCourse)cards=cards.filter(c=>c.courseId===onlyCourse);
 const due=reviewQueue(cards,state);const selected=(due.length?due:cards).slice(0,({5:3,15:7,25:12})[state.duration]);
 if(!selected.length){toast('Add a source-linked card to this course first.');return;}
 session={cards:selected,index:0,phase:'warmup',attemptId:uid(),hint:false,revealed:false,response:'',submitted:false,results:[],warmupResult:null};if(detailViews.practice)render();go('practice');
}
function practicePage(){if(!session)return `<div class="empty"><h2>Your next small step awaits.</h2><p>Choose a time budget and start when you’re ready.</p><button class="btn primary" data-action="start">Start study session</button></div>`;
 if(session.phase==='warmup')return `${pageHead('EASE INTO IT','A little warm-up?','Take about 2–3 minutes, or skip straight to your review. There’s no countdown.')}<section class="practice-card panel"><span class="pill mint">OPTIONAL · HYPOTHETICAL SCENARIO</span><h2>You want a new laptop, but cannot afford it. Is this demand?</h2><p class="muted small">Try recalling the condition that turns a want into demand.</p><div class="stack section-space"><button class="answer-option" data-action="warmup" data-id="no">No — it is a want without the buying power.</button><button class="answer-option" data-action="warmup" data-id="yes">Yes — any strong desire is demand.</button></div>${session.warmupResult?`<div class="feedback"><strong>${session.warmupResult==='no'?'You found the key distinction.':'There’s one condition to add.'}</strong><p>Demand requires buying power. This scenario describes a want, not a want backed by resources.</p><a href="assets/marketing-source-pages.pdf#page=1" target="_blank" rel="noopener">Source: printed p. 30 / original PDF p. 31</a></div>`:''}<div class="actions"><button class="btn primary" data-action="begin-recall">${session.warmupResult?'Continue to recall':'Skip warm-up'} ${icon('arrow',14)}</button><a href="#study" class="btn outline">Back to Study Room</a></div><p class="source-note">Warm-up feedback is for orientation; it does not raise course mastery.</p></section>`;
 if(session.phase==='done')return `${pageHead('A LITTLE PROGRESS, SAVED','That was time well spent.','You gave your ideas a workout. Their next review dates are ready.')}<section class="practice-card panel"><span class="pill mint">SESSION COMPLETE</span><h2>${session.results.length} ${session.results.length===1?'idea':'ideas'} revisited.</h2><p class="muted">Your answers and review dates are saved on this browser. Keep going when you feel ready, or let the ideas settle.</p>${session.results.map(id=>`<div class="check-row"><div class="check-copy"><strong>${e(allCards().find(c=>c.id===id)?.question||'Review card')}</strong><small>Next review: ${dateLabel(state.reviews[id].nextReview)}</small></div>${icon('check',16)}</div>`).join('')}<div class="actions"><a class="btn primary" href="#study">See my progress ${icon('arrow',14)}</a><a class="btn outline" href="#home">Back to The Daily</a></div></section>`;
 const c=session.cards[session.index];return `${pageHead('ACTIVE RECALL','Your own words first.',e(courseName(c.courseId)))}<section class="practice-card panel"><div class="between"><span class="pill blue">CARD ${session.index+1} OF ${session.cards.length}</span><span class="small muted">${state.duration} min budget · your pace</span></div><h2>${e(c.question)}</h2><label class="small muted" for="recall-answer">Think it through, then write your answer.</label><textarea id="recall-answer" placeholder="What do you remember? A few words are a start." ${session.revealed?'readonly':''}>${e(session.response)}</textarea>${session.hint?`<div class="info-strip">${icon('info',15)}${e(c.hint||'Try connecting the concept to the source section you read.')}</div>`:''}${session.revealed?`<div class="feedback"><strong>A reference answer</strong><p>${e(c.answer)}</p>${sourceLink(c)}<p class="tiny">Compare your explanation with the reference. This is your self-assessment, not automatic grading.</p></div><div class="actions"><button class="btn outline" data-action="rate" data-id="again" ${session.submitted?'disabled':''}>Needs another look</button><button class="btn outline" data-action="rate" data-id="hard" ${session.submitted?'disabled':''}>Recalled with effort</button><button class="btn primary" data-action="rate" data-id="good" ${session.submitted||!session.response.trim()?'disabled':''}>Recalled correctly</button></div>`:`<div class="actions"><button class="btn primary" data-action="reveal">Compare with the answer ${icon('arrow',14)}</button><button class="btn outline" data-action="hint">${session.hint?'Hint shown':'A small hint'}</button></div>`}<p class="source-note">${e(c.sourceLabel)}</p></section>`;
}
function sourceLink(c){const url=typeof c.sourceUrl==='string'&&/^(https:\/\/|assets\/)/.test(c.sourceUrl)?c.sourceUrl:'assets/marketing-source-pages.pdf';return c.documentId?`<button class="text-btn" data-action="reader" data-id="${e(c.documentId)}">Open source section ${icon('arrowUp',13)}</button>`:`<a href="${e(url)}" target="_blank" rel="noopener" class="text-btn">Read the source ${icon('arrowUp',13)}</a>`;}
function rate(result){if(!session||session.submitted||!session.revealed)return;session.submitted=true;const c=session.cards[session.index];applyAttempt(state,{id:session.attemptId,cardId:c.id,at:new Date().toISOString(),result,response:session.response,hintUsed:session.hint,answerBeforeRecall:!session.response.trim(),answerViewed:true,assessment:'self'});if(!persist()){session.submitted=false;return;}session.results.push(c.id);session.index++;if(session.index>=session.cards.length)session.phase='done';else{session.attemptId=uid();session.hint=false;session.revealed=false;session.response='';session.submitted=false;}render();$('#practice').focus({preventScroll:true});}

function uploadDialog(courseId=''){openModal('Bring a book to your desk',`<p>Choose a course and attach a local document. It stays on this device; no document is sent to an AI service. New versions keep earlier cards and learning history.</p><form id="upload-form"><div class="form-field"><label for="upload-course">Course</label><select id="upload-course" name="course">${allCourses().map(c=>`<option value="${c.id}" ${courseId===c.id?'selected':''}>${e(c.name)}</option>`).join('')}</select></div><div class="dropzone">${icon('upload',28)}<h3>Make room for a new idea</h3><p>PDF up to 100 MB · DOCX / PPTX up to 30 MB</p><input type="file" name="document" id="document-file" accept=".pdf,.docx,.pptx" required aria-label="Choose PDF, DOCX or PPTX"></div><p class="source-note">Text extraction only. Scans need OCR elsewhere; tables, diagrams and images should be checked in the original. Legacy .ppt is not supported.</p><div id="upload-status" class="source-note" role="status"></div><div class="actions"><button class="btn primary" type="submit">Attach & open ${icon('arrow',14)}</button></div></form>`);}
async function upload(form){const button=form.querySelector('button[type=submit]'),status=$('#upload-status'),file=form.elements.document.files[0];if(!file)return;button.disabled=true;try{
 status.textContent='Checking file type, size and version…';const checked=await inspectFile(file);const courseId=form.elements.course.value;
 const existing=state.documents.find(d=>(d.hash||d.id)===checked.id&&d.courseId===courseId);
 if(existing){await putFile(existing.id,file);closeModal();await openReader(existing.id);toast('This version is already in your collection. Original file reattached.');return;}
 status.textContent='Opening document on this device…';let pages=1,sections=[];
 if(checked.type==='pdf'){const pdf=await loadPdf(checked.bytes);pages=pdf.numPages;await pdf.destroy();}
 else{sections=await officeSections(checked.bytes,checked.type);pages=sections.length;}
 const id=state.documents.some(d=>d.id===checked.id)?checked.id+'-'+courseId:checked.id;
 await putFile(id,file);
 const doc={id,hash:checked.id,name:file.name,courseId,type:checked.type,pages,sections,added:new Date().toISOString(),bytes:file.size};state.documents.push(doc);if(!persist()){state.documents.pop();throw Error('Could not save document metadata. Export a backup and free browser storage, then retry.');}
 closeModal();await openReader(id);toast('Document attached. Choose a section to study.');
}catch(err){status.className='error section-space';status.textContent=err.message||'Could not read this document. Try a fresh export.';}finally{button.disabled=false;}}
async function openReader(id,selectedPage=null){const doc=state.documents.find(d=>d.id===id);if(!doc)return toast('Document not found. Attach the original again.');
 openModal('Opening your book',`<p role="status">Loading ${e(doc.name)} from this browser…</p>`);
 try{const blob=await getFile(id);if(!blob)throw Error('The original file is not stored on this browser. Use Add document to reattach it; your notes and reviews are safe.');if(reader?.url)URL.revokeObjectURL(reader.url);if(reader?.pdf)await reader.pdf.destroy();reader={doc,blob,pdf:null,page:Math.min(selectedPage||state.bookmarks[id]||1,doc.pages),url:URL.createObjectURL(blob)};if(doc.type==='pdf'){reader.pdf=await loadPdf(new Uint8Array(await blob.arrayBuffer()));const firstPage=await reader.pdf.getPage(reader.page);const size=firstPage.getViewport({scale:1});reader.canvasWidth=size.width;reader.canvasHeight=size.height;}closeModal();contentDirty=true;go('reader/'+id);}catch(err){openModal('Let’s reconnect this book',`<p>${e(err.message)}</p><div class="actions"><button class="btn primary" data-action="upload" data-id="${e(doc.courseId)}">Reattach original</button><a class="btn outline" href="#course/${e(doc.courseId)}" data-action="close-modal">Back to course</a></div>`);}}
function readerPage(){if(!reader||reader.doc.id!==param)return `<div class="empty"><h2>Your reading place is saved.</h2><p>Reopen the local document to continue.</p><button class="btn primary" data-action="reader" data-id="${e(param)}">Open book</button></div>`;const d=reader.doc;return `${pageHead('THE READING ROOM',e(courseName(d.courseId)),e(d.name))}<div class="reader-controls"><button class="btn outline" data-action="prev-page" ${reader.page<=1?'disabled':''}>← Previous</button><label class="small" for="reader-page">${d.type==='pptx'?'Slide':d.type==='docx'?'Section':'PDF page'}</label><input id="reader-page" type="number" value="${reader.page}" min="1" max="${d.pages}" aria-label="Page or section number"><span class="small muted">of ${d.pages}</span><button class="btn outline" data-action="next-page" ${reader.page>=d.pages?'disabled':''}>Next →</button><button class="btn outline" data-action="bookmark-page">${icon('bookmark',15)} Save place</button><a href="${reader.url}" class="btn outline" target="_blank" rel="noopener" ${d.type!=='pdf'?`download="${e(d.name)}"`:''}>Original ${icon('arrowUp',14)}</a></div><div class="reader-layout"><section class="panel reader-page"><div id="reader-render-status" class="source-note" role="status">Opening page…</div>${d.type==='pdf'?`<canvas class="reader-canvas" id="pdf-canvas" aria-label="Original PDF page" width="${reader.canvasWidth||300}" height="${reader.canvasHeight||150}"></canvas>`:'<pre id="office-text"></pre>'}<details><summary>Extracted text for this page</summary><pre id="page-text">Use Extract selected pages to read the text here.</pre></details></section><aside><section class="panel panel-pad"><h3>Choose a manageable section</h3><p class="source-note">Text-based highlights preserve source wording. They are not an AI synthesis; diagrams and tables need the original.</p><form id="extract-form"><div class="form-grid"><div class="form-field"><label for="range-start">From</label><input id="range-start" name="start" type="number" min="1" max="${d.pages}" value="${reader.page}" required></div><div class="form-field"><label for="range-end">To</label><input id="range-end" name="end" type="number" min="1" max="${d.pages}" value="${Math.min(d.pages,reader.page+2)}" required></div></div><button class="btn primary" type="submit">Extract selected ${d.type==='pptx'?'slides':'pages'}</button><div id="extract-status" class="source-note" role="status">Up to 30 sections per batch. Saved extracts are reused.</div></form><div id="highlights"></div></section><section class="panel panel-pad section-space"><h3>Turn an idea into recall</h3><p class="source-note">After checking the original, write a question and reference answer linked to this page.</p><button class="btn outline section-space" data-action="new-card" ${d.sections.find(s=>s.page===reader.page&&s.text.trim().length>=60)?'':'disabled'}>${icon('plus',15)} Create review card</button><div class="form-field"><label for="doc-note">Notes for this version</label><textarea id="doc-note" placeholder="What matters here?">${e(state.notes[d.id]||'')}</textarea></div><button class="text-btn" data-action="save-doc-note">Save notes ${icon('check',14)}</button></section></aside></div>`;}
async function drawReader(){const token=++readerToken,local=reader;try{if(local.pdf){const p=await local.pdf.getPage(local.page);if(token!==readerToken)return;const canvas=$('#pdf-canvas');if(!canvas)return;const scale=Math.min(2,canvas.parentElement.clientWidth/p.getViewport({scale:1}).width);const viewport=p.getViewport({scale});canvas.width=local.canvasWidth=viewport.width;canvas.height=local.canvasHeight=viewport.height;await p.render({canvasContext:canvas.getContext('2d'),viewport}).promise;}else $('#office-text').textContent=local.doc.sections[local.page-1]?.text||'No readable text. Open the original document.';if(token!==readerToken)return;$('#reader-render-status').textContent=local.doc.type==='pdf'?'Original PDF · page '+local.page:'Extracted Office text · layout and images are not reproduced.';const section=local.doc.sections.find(s=>s.page===local.page);$('#page-text').textContent=section?.text||'This page has not been extracted yet.';if(section?.warning)$('#reader-render-status').textContent=section.warning;}catch(err){if($('#reader-render-status'))$('#reader-render-status').textContent='This page could not be displayed. Open the original file or try another page.';}}
async function extract(form){if(!reader)return;const status=$('#extract-status'),button=form.querySelector('button'),start=Number(form.elements.start.value),end=Number(form.elements.end.value);button.disabled=true;try{
 if(!Number.isInteger(start)||!Number.isInteger(end)||start<1||end<start||end>reader.doc.pages||end-start>=30)throw Error('Select an ordered range of up to 30 sections within this document.');
 let sections=[];if(reader.pdf){const needed=[];for(let p=start;p<=end;p++)if(!reader.doc.sections.some(s=>s.page===p&&!s.warning))needed.push(p);
 for(let i=0;i<needed.length;i++){status.textContent=`Reading page ${needed[i]} · ${i+1} of ${needed.length}…`;sections.push(...await pdfSections(reader.pdf,needed[i],needed[i]));}
 const map=new Map(reader.doc.sections.map(s=>[s.page,s]));sections.forEach(s=>map.set(s.page,s));reader.doc.sections=[...map.values()].sort((a,b)=>a.page-b.page);persist();}
 sections=reader.doc.sections.filter(s=>s.page>=start&&s.page<=end);const highlights=extractHighlights(sections),warnings=sections.filter(s=>s.warning);$('#highlights').innerHTML=`<h3 class="section-space">Source highlights</h3><p class="source-note">Selected source sentences, not a complete summary.</p>${highlights.length?highlights.map(h=>`<div class="preview-highlight"><span class="pill blue">${reader.doc.type==='pptx'?'SLIDE':'SECTION'} ${h.page}</span><p style="margin-top:8px">${e(h.text)}</p></div>`).join(''):'<div class="error section-space">Not enough reliable text to create highlights. Use the original or an OCR tool. No knowledge has been generated.</div>'}${warnings.map(s=>`<p class="error section-space">Section ${s.page}: ${e(s.warning)}</p>`).join('')}`;status.textContent=`Saved ${sections.length} sections. ${warnings.length} need a source check.`;$('#page-text').textContent=reader.doc.sections.find(s=>s.page===reader.page)?.text||'This page is outside the selected range.';const newCard=$('[data-action="new-card"]');if(newCard)newCard.disabled=!reader.doc.sections.some(s=>s.page===reader.page&&s.text.trim().length>=60);
}catch(err){status.textContent=err.message;status.className='error section-space';}finally{button.disabled=false;}}
function cardDialog(id){const old=state.cards.find(c=>c.id===id),d=reader?.doc;if(!old&&!d)return;const page=old?.page||reader.page,documentId=old?.documentId||d.id;openModal(old?'Refine your recall card':'Capture one useful idea',`<p>A specific question, a checked answer, and a source you can return to.</p><form id="card-form" data-id="${e(old?.id||'')}" data-doc="${e(documentId)}" data-page="${page}"><div class="form-field"><label for="card-question">Question</label><textarea id="card-question" name="question" maxlength="1500" required placeholder="What should you be able to explain without looking?">${e(old?.question||'')}</textarea></div><div class="form-field"><label for="card-answer">Reference answer</label><textarea id="card-answer" name="answer" maxlength="6000" required placeholder="Check the original section before writing this.">${e(old?.answer||'')}</textarea></div><div class="form-field"><label for="card-hint">A small hint (optional)</label><input id="card-hint" type="text" name="hint" maxlength="500" value="${e(old?.hint||'')}"></div><p class="source-note">Source: ${e(old?.sourceLabel||`${d.name} · section ${page}`)}. Existing review history is preserved when you edit.</p><button class="btn primary" type="submit">Save card ${icon('check',15)}</button></form>`);}
function downloadFile(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backup(){state.lastBackup=new Date().toISOString();persist();downloadFile('zin-studio-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({kind:'zin-studio-backup',version:1,exportedAt:new Date().toISOString(),includesOriginalFiles:false,state},null,2));toast('Progress backup exported. Keep original books separately.');}
function importDialog(){openModal('Bring your progress back',`<p>This merges a Studio JSON backup into your current data. Existing local notes and edits take priority; attempts are deduplicated. Original documents need to be reattached separately.</p><form id="backup-form"><div class="form-field"><label for="backup-file">Studio backup file</label><input id="backup-file" type="file" name="backup" accept=".json" required></div><div id="backup-status" role="status"></div><button class="btn primary" type="submit">Validate & merge backup</button></form>`);}
function setTheme(theme){document.documentElement.dataset.theme=theme;try{localStorage.setItem('zin-theme',theme);}catch{toast('Theme changed for this visit; browser storage is unavailable.');}render();}

document.addEventListener('click',async ev=>{
 const link=ev.target.closest('a[href^="#"]');
 if(link&&!ev.defaultPrevented&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey&&!ev.altKey&&ev.button===0){
  const path=link.getAttribute('href').slice(1),key=path.split('/')[0];
  if(Object.hasOwn(sectionNames,key)||Object.hasOwn(detailParents,key)){ev.preventDefault();go(path);return;}
 }
 const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;
 try{switch(a){
 case 'news-next':moveNews(id,1);break;
 case 'news-prev':moveNews(id,-1);break;
 case 'course-link':courseLinkDialog(id);break;
 case 'refresh-news':await updateReading(true);break;
 case 'case-tab':caseMode=id;refreshCasePanel();break;
 case 'case-next':caseOffset++;refreshCasePanel();break;
 case 'case-prev':caseOffset--;refreshCasePanel();break;
 case 'case-open':openCase(id);break;
 case 'case-read':if(!state.caseRead.includes(id))state.caseRead.push(id);persist();b.textContent='Đã đọc';refreshCasePanel();toast('Đã lưu hoạt động đọc; không cộng vào mức độ hiểu bài.');break;
 case 'case-save-note':state.notes['case:'+id]=$('#case-reflection').value;if(persist())toast('Đã lưu suy ngẫm của bạn.');break;
 case 'case-source-page':await openReader(id,Number(b.dataset.page));break;
 case 'menu':{const s=$('.sidebar');s.classList.toggle('open');b.setAttribute('aria-expanded',s.classList.contains('open'));break;}
 case 'theme':setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');break;
 case 'set-theme':setTheme(id);break;
 case 'course':go('course/'+id);break;
 case 'close-modal':closeModal();break;
 case 'save-story':rememberStory(allNews().find(n=>n.id===id));state.saved=toggle(state.saved,id);persist();render();toast(state.saved.includes(id)?'A good idea, saved.':'Story removed from saved.');break;
 case 'story':story(id);break;
 case 'mark-read':if(!state.read.includes(id))state.read.push(id);persist();b.textContent='Marked as read';toast('Reading activity saved separately from learning.');break;
 case 'hide-story':state.hidden=[...new Set([...state.hidden,id])];persist();closeModal();render();toast('Story hidden. Restore it in news preferences.');break;
  case 'reset-news':state.hidden=[];state.newsTopics=[];persist();closeModal();render();break;
 case 'duration':state.duration=Number(id);persist();render();break;
 case 'start':startSession();break;
 case 'practice-lesson':startSession(id);break;
 case 'practice-course':startSession(null,id);break;
 case 'warmup':session.warmupResult=id;render();break;
 case 'begin-recall':session.phase='recall';render();break;
 case 'hint':session.response=$('#recall-answer').value;session.hint=true;render();break;
 case 'reveal':session.response=$('#recall-answer').value;session.revealed=true;render();break;
 case 'rate':rate(id);break;
 case 'method':method();break;
 case 'complete-lesson':if(!state.completed.includes(id))state.completed.push(id);persist();render();toast('Reading saved. Recall practice is tracked separately.');break;
 case 'save-note':state.notes[id]=$('#lesson-note').value;if(persist())toast('Your words, saved.');break;
 case 'save-doc-note':state.notes[reader.doc.id]=$('#doc-note').value;if(persist())toast('Notes saved for this document version.');break;
 case 'upload':uploadDialog(id||'');break;
 case 'reader':await openReader(id);break;
 case 'prev-page':case 'next-page':if(reader){reader.page=Math.max(1,Math.min(reader.doc.pages,reader.page+(a==='prev-page'?-1:1)));render();}break;
 case 'bookmark-page':state.bookmarks[reader.doc.id]=reader.page;if(persist())toast('Reading place saved.');break;
 case 'new-card':cardDialog();break;
 case 'edit-card':cardDialog(id);break;
 case 'new-course':openModal('A fresh space for a subject',`<form id="course-form"><div class="form-field"><label for="course-name">Course name</label><input type="text" id="course-name" name="name" maxlength="120" required placeholder="The actual name of your course"></div><button class="btn primary" type="submit">Create course</button></form>`);break;
 case 'backup':backup();break;
 case 'import-backup':importDialog();break;
 case 'raw-backup':downloadFile('zin-studio-original-data.txt',localStorage.getItem('zin-studio-v1')||'','text/plain');break;
 }}catch(err){toast(err.message||'Something went wrong. Your existing progress is safe.');}
});
document.addEventListener('submit',async ev=>{const f=ev.target;ev.preventDefault();try{switch(f.id){
 case 'course-link-form':{try{const url=courseSiteUrl(f.elements.url.value),previous=state.courseLinks[f.dataset.id];state.courseLinks[f.dataset.id]=url;if(persist()){closeModal();render();toast(url?'Đã gắn website môn học.':'Đã bỏ liên kết website.');}else{if(previous===undefined)delete state.courseLinks[f.dataset.id];else state.courseLinks[f.dataset.id]=previous;}}catch(error){$('#course-link-error').textContent=error.message;}break;}
 case 'global-search':libraryFilter=f.elements.query.value.trim();render();go('library');break;
 case 'upload-form':await upload(f);break;
 case 'extract-form':await extract(f);break;
 case 'course-form':{const name=f.elements.name.value.trim();if(!name)return;if(allCourses().some(c=>c.name.toLowerCase()===name.toLowerCase()))return toast('This course is already on your shelf.');const c={id:'course-'+uid(),name,books:[],image:'assets/library.webp',current:false};state.courses.push(c);persist();closeModal();go('course/'+c.id);break;}
 case 'card-form':{const question=f.elements.question.value.trim(),answer=f.elements.answer.value.trim();if(!question||!answer)return toast('Add both a question and a checked answer.');const d=state.documents.find(x=>x.id===f.dataset.doc);if(!d)return;const old=state.cards.find(c=>c.id===f.dataset.id);if(old){old.question=question;old.answer=answer;old.hint=f.elements.hint.value.trim();old.edited=new Date().toISOString();}else state.cards.push({id:uid(),question,answer,hint:f.elements.hint.value.trim(),courseId:d.courseId,documentId:d.id,page:Number(f.dataset.page),sourceLabel:`${d.name} · section ${f.dataset.page} · version ${d.id.slice(0,8)}`,created:new Date().toISOString()});if(persist()){closeModal();toast('Card saved with its source. Find it in your course or Study Room.');}break;}
 case 'backup-form':{const status=$('#backup-status');try{const file=f.elements.backup.files[0];if(!file||file.size>25*1024*1024)throw Error('Choose a Studio JSON backup under 25 MB.');const data=JSON.parse(await file.text());if(data.kind!=='zin-studio-backup'||data.version!==1)throw Error('This is not a Studio backup.');const incoming=validateState(data.state),merged=mergeState(state,incoming);saveState(merged);state=merged;storageError='';closeModal();render();toast('Backup merged. Existing edits and review history preserved.');}catch(err){status.className='error section-space';status.textContent=err.message;}break;}
 }}catch(err){toast(err.message||'Could not save. Please try again.');}});
document.addEventListener('change',ev=>{const t=ev.target;if(t.id==='case-document-section'){localCaseId=t.value;refreshCasePanel();}if(t.id==='library-term'){libraryTerm=t.value;render();}if(t.id==='reader-page'&&reader){const n=Number(t.value);if(Number.isInteger(n)&&n>=1&&n<=reader.doc.pages){reader.page=n;render();}else{t.value=reader.page;toast('Choose a page within this book.');}}});
document.addEventListener('input',ev=>{if(ev.target.id==='library-search'){const pos=ev.target.selectionStart;libraryFilter=ev.target.value;render();const input=$('#library-search');input.focus();input.setSelectionRange(pos,pos);}if(ev.target.id==='recall-answer'&&session)session.response=ev.target.value;});
document.addEventListener('keydown',ev=>{if(ev.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!modal.open){ev.preventDefault();$('#global-search input')?.focus();}if(ev.key==='Escape'){$('.sidebar')?.classList.remove('open');$('.mobile-menu')?.setAttribute('aria-expanded','false');}});
addEventListener('hashchange',()=>navigateToHash());
addEventListener('scroll',()=>{
 if(scrollFrame)return;
 scrollFrame=requestAnimationFrame(()=>{
  scrollFrame=0;const offset=($('.topbar')?.getBoundingClientRect().bottom||80)+24;
  const sections=[...document.querySelectorAll('[data-section]')];
  const current=sections.find(el=>el.getBoundingClientRect().top<=offset&&el.getBoundingClientRect().bottom>offset)||sections.find(el=>el.getBoundingClientRect().top>offset);
  if(current)setActiveSection(current.dataset.section);
 });
},{passive:true});
history.scrollRestoration='manual';
try{const response=await fetch('data/reference.json');if(!response.ok)throw Error('Could not load your course catalog.');reference=await response.json();render();navigateToHash(false);updateReading();loadMaterials();}catch(err){app.innerHTML=`<div class="boot"><h1>The studio needs another moment.</h1><p>${e(err.message)}</p><button class="btn primary" onclick="location.reload()">Try again</button></div>`;}

setInterval(()=>{if(!document.hidden)updateReading();},REFRESH_MS);
